insert into public.chapters (series_id, season_number, week, day, script, meta) values
('dark-moon', 1, 5, 1, $json${"week":5,"day":1,"title":"The grey afternoon","heading":"The grey afternoon","question":"Meira never found a fifth. Where do you look for a Stone no record names?","steps":[{"t":"say","text":"A third beat. Then a fourth. You feel each one in your teeth and the soles of your feet more than you hear it: slow as a sleeper's heart, from somewhere far to the north.\n\nThe dawn never finishes. The morning stays grey and thin, as if the sun had been pushed a long way off, and along the whole shore of the Stillwater the birds have stopped singing."},{"t":"say","text":"You row Joss home. He sits in the bow with his bandaged hand in his lap, and the little boat in the other.\n\nHis grandmother is already down on the shingle, in the strange light, with her hands over her mouth. She gets him out of the boat by herself.\n\nShe does not put him down. She carries him up the shingle the way she must have carried him when he was two, with his feet knocking against her knees, and he lets her.\n\nAt the top of the lane he twists round in her arms and holds the little boat up over her shoulder, high, so that all of you can see he still has it."},{"t":"notice","lines":{"Might":{"first":"She lifts him clear of the gunwale as if he weighed nothing.","second":"She has not been strong enough for that in years."},"Agility":{"first":"You feel each beat come up through the boat's planks before it reaches your ears.","second":"It travels in the ground, and in the water."},"Intellect":{"first":"It is long past sunrise, and the light has not changed.","second":"This is not weather."},"Charm":{"first":"Up the lane, the lamp is still burning in her window.","second":"Nobody has thought to put it out. Nobody can tell that it is day."},"Craft":{"first":"Joss's little boat has lost its mast.","second":"He held on to it so hard that it broke."},"Aim":{"first":"The beats come from one quarter and no other.","second":"North, and a little east of north."}}},{"t":"say","text":"Four children home. Every one you were sent to find.\n\nAnd the thing they were used for is waking up."},{"t":"say","text":"The torn page is still in your hand: *what the four begin, the fifth shall end—*\n\nMeira never found a fifth place. Every record she had said four."},{"t":"say","text":"At the head of the north road out of Reedham stands a waystone older than the village, its carving worn to nothing."},{"t":"challenge","title":"THE WAYSTONE","desc":"It said something once.","options":[{"attr":"Craft","verb":"charcoal and a sheet from Meira's notebook: take a rubbing, as you did on the forest road"},{"attr":"Intellect","verb":"read the old hand by the shapes it left, with the light held low across the stone"}],"reward":"+500g","fail":"the stone keeps its word"},{"t":"say","text":"One word comes up, in the old hand, letter by letter.\n\n**HIGHWALL**\n\nBeside the word, in the same hand, is a number: the miles. Whoever took the knife to this stone left the distance alone.\n\nUnder it there was a second line. It did not wear away. Somebody cut it out, stroke by stroke, with a patient knife.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"Nothing comes up that you can read. The stone keeps its word, and you will have to be told it. Only this: under the worn part there was a second line, and it did not wear away. Somebody cut it out, stroke by stroke, with a patient knife.","cond":{"on":"challenge","pass":false}},{"t":"act","label":"ASK GARRICK WHERE A FIFTH WOULD BE"},{"t":"say","text":"Garrick is looking north, the way the heartbeat comes from.\n\n*\"The fifth wasn't hidden in the hills like the others,\"* he says. *\"Every telling I know ends at Highwall.\"*"},{"t":"say","text":"Highwall. You all learned it as children: the old capital, where the Grey Host broke of a fever in its own camp, and the city was spared by luck.\n\nYou know now what the luck was.\n\nThe carter's coin is in your pocket: a king's face, scraped down to bare metal. The line cut out of this stone is the same work. The story you were taught is what was left when the scraping was done."},{"t":"say","text":"In a crack at the waystone's foot, with a rime of frost on it though the day is mild:"},{"t":"act","label":"TAKE IT"},{"t":"say","text":"**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"At dusk the heartbeat comes again. It is louder than it was at dawn.\n\n**What is left in a city where nothing grows and nobody goes? The old kingdom's road: two days north.**","pull":true},{"t":"summary","lines":["**THE GREY AFTERNOON** · Day 1","You earned: `[gold]` · Craft or Intellect `[growth]`","You learned: the fifth is at **Highwall**, the dead capital at the end of the old kingdom's road: the way the heartbeat comes from. The story you learned about it as a child has had something cut out of it. Joss is home.","*On a failure:* You missed something at the waystone. Someone at the fire may have seen it.","Fragment: 1 found, locked","Tomorrow: **the old kingdom's road**"]}]}$json$::jsonb, $json${"dc":9,"wDef":25,"wAtk":18,"fightReward":0}$json$::jsonb),
('dark-moon', 1, 5, 2, $json${"week":5,"day":2,"title":"The old kingdom's road","heading":"The old kingdom's road","question":"what is the heartbeat doing to the country?","steps":[{"t":"say","text":"The road was built to carry armies. It still runs straight as a spear across the empty country, but grass has grown up through its stones, and nobody has mended it in longer than anyone can say.\n\nEvery mile has its stone, and every stone a number, one less than the last."},{"t":"say","text":"Late in the afternoon the road passes between two long, low rows of grassy mounds, one on each side, running away across the fields in perfect lines."},{"t":"say","text":"Drawn up at the head of the rows are the only people you have met all day. A family, come down from the north, with all they own on one cart, and a cow tied behind."},{"t":"act","label":"WHAT DID YOU SEE?"},{"t":"say","text":"The man answers without turning round. *\"The beasts won't settle. Not since the sky turned.\"*\n\nIt is not an army they are running from. It is their own yard. The dogs first, and then the pigs. He has a bandage on his forearm, and the cow is the only animal they have left that will still be led.\n\nA child on the tailboard counts you, with one finger."},{"t":"act","label":"WALK IN AMONG THEM"},{"t":"say","text":"Every mound is the same length. A man's length.\n\nThey are graves. Hundreds, dug in straight rows, the way soldiers bury soldiers: the ones who fell in the war, before the last wall.\n\nAmong them, one is new. The turf was cut this week and laid back badly, by people with no time to do better."},{"t":"notice","lines":{"Might":{"first":"The new grave is shallow.","second":"Whoever dug it could not stay to dig deeper."},"Agility":{"first":"The family's cow has not stood still once since the cart stopped.","second":"She keeps her head to the south."},"Intellect":{"first":"Hundreds of graves, and not one of them marked with a name.","second":"They were buried by people who knew every one of them."},"Charm":{"first":"The family walks wide of the new grave, and the child is turned to face the other way.","second":"They know whose it is."},"Craft":{"first":"At the end of the rows stands one block that is no grave.","second":"It is cut like the waystone at Reedham."},"Aim":{"first":"The rows run dead straight, and they all point one way.","second":"North. At the city."}}},{"t":"say","text":"At the rows' end, the block's top lifts off like a lid."},{"t":"act","label":"LIFT IT"},{"t":"say","text":"**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"The light is going. The family will stay where you stay."},{"t":"choice","id":0,"labels":["CAMP AT THE HEAD OF THE ROWS","CAMP ON THE OPEN ROAD"],"mode":"pick","branches":[{"options":[0],"text":"The mounds break the wind. They also hide whatever is beyond them."},{"options":[1],"text":"Nothing can come at you unseen. Nothing will fail to see you, either."}]},{"t":"say","text":"At dusk the heartbeat comes.\n\nThe grass on the graves shivers with it, row after row, like the hide of a horse. The cow screams and throws herself against her rope.\n\nAnd out of the dusk come the dogs."},{"t":"fight","name":"WHAT WAS A FARM DOG","desc":"It still has its collar on.","firstLines":["On the road, you saw them come: you strike first.","Among the rows, they came over the mounds: it strikes first."],"strikeFirst":{"on":"choice","choice":0,"options":[1]}},{"t":"say","text":"The cart is in the middle of it, and the child is under the cart, and between you nothing reaches either.\n\nThen the beat stops. The dogs stop with it. They stand a moment, heads down, as if they had forgotten what they came for, and go away into the dark."},{"t":"say","text":"The one you beat is the last to go. It looks back at you from the edge of the dark and wags its tail, once, as if asking what it has done.","cond":{"on":"fight","won":true}},{"t":"say","text":"In the morning the family goes south. The child on the tailboard watches you all the way to the bend."},{"t":"say","text":"**It is nearer every dusk, and it is coming from inside the city. Highwall, by noon.**","pull":true},{"t":"summary","lines":["**THE OLD KINGDOM'S ROAD** · Day 2","You earned: `[gold]`","You learned: the heartbeat is **turning the beasts**, and people are leaving the north. The road runs through hundreds of war graves, and one new one. **When the beat comes, the ground moves with it.**","Fragments: 2 found","Tomorrow: **Highwall**"]}]}$json$::jsonb, $json${"dc":9,"wDef":25,"wAtk":18,"fightReward":300}$json$::jsonb),
('dark-moon', 1, 5, 3, $json${"week":5,"day":3,"title":"The herald's gate","heading":"The herald's gate","question":"how do you get in, and where in a whole dead city do you start?","steps":[{"t":"say","text":"Highwall comes up out of the grey noon all at once: a wall so long that it bends out of sight in both directions, and behind it, rising in terraces, a city of pale stone.\n\nIt is not ruined. The walls are whole. The towers are whole. But nothing grows between the stones, not moss, not the smallest green thing, and there are no birds.\n\nOn its hill at the very top stands a great hall. Its doors are shut."},{"t":"say","text":"The road runs straight to a gate. *Their herald rode up to the gate and named the hour of the city's ending — dawn.*\n\nThis is the wall they held that night.\n\nThe gate is shut."},{"t":"notice","lines":{"Might":{"first":"The gate's timbers have not sagged a finger's width.","second":"Something on the far side is holding them up."},"Agility":{"first":"The stair to the wall has lost its middle.","second":"What is left of it would take one person at a time."},"Intellect":{"first":"A dead city has no reason to shut its gate.","second":"And nobody left to do it."},"Charm":{"first":"Nobody has spoken since the wall came into sight.","second":"It is not a place that wants talking in."},"Craft":{"first":"The gate-tower door is iron, and rusted into its frame.","second":"The hinges are on your side."},"Aim":{"first":"High up, above the terraces, one grey thread stands in the grey air.","second":"It is not cloud."}}},{"t":"challenge","title":"THE WALL","desc":"The gate will not open. The wall is another matter.","options":[{"attr":"Aim","verb":"read the broken stair from its foot, and set your feet only where it will hold"},{"attr":"Might","verb":"force the rusted door of the gate-tower"}],"reward":"+500g","fail":"it takes what is left of the afternoon, and you see the city only by dusk"},{"t":"say","text":"You are up in minutes, with the afternoon still in hand.\n\nThere is light enough to follow one street all the way up to the hall. Something is standing in it: a dozen dark shapes, spaced out down the middle of the road like posts.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"It takes what is left of the afternoon. You are up, but the light is going, and the city below you is only roofs and shadow.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"Garrick passes his flask along the walkway, and waits until the last of you has had some before he takes any himself."},{"t":"act","label":"LOOK DOWN AT THE GATE"},{"t":"say","text":"From above, you can see its inner side.\n\nIt is barred. The bar is new timber, still pale.\n\nThe iron brackets it lies in are another matter. They are worn smooth, and bright, by more bars than anyone could count."},{"t":"press","title":"GO DOWN TO IT","detail":"inside the wall, by the gatehouse stair","harder":4,"reward":"+200g, and one more detail"},{"t":"say","text":"Stacked against the gatehouse wall, one upon another, lie the old bars. Dozens. The topmost are grey. The lowest have rotted to a brown line on the stone.\n\nWhoever changes the bar has kept every one.","cond":{"on":"press"}},{"t":"say","text":"On the walkway above the gate, where they would have stood shoulder to shoulder, a carved housing is set into the parapet at chest height."},{"t":"act","label":"PRESS YOUR PALM FLAT TO IT"},{"t":"say","text":"Its stone face swings inward.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"You are standing where they stood. The trail for the fifth begins on their own stretch of wall."},{"t":"say","text":"And from here you can see what that grey thread is. Smoke. One fire, below the hall."},{"t":"say","text":"**Who bars a dead city from the inside, year after year? Down into the streets, following the wall.**","pull":true},{"t":"summary","lines":["**THE HERALD'S GATE** · Day 3","You earned: `[gold]` · Aim or Might `[growth]`","You learned: Highwall's gate is **barred from the inside**: new timber, in brackets worn bright by centuries of bars. Somebody has always kept it shut, and is keeping it shut now. One fire is burning below the hall.","*On a failure:* You missed something on the wall. Someone at the fire may have seen it.","Fragments: 3 found","Tomorrow: **the dead streets**"]}]}$json$::jsonb, $json${"dc":9,"wDef":25,"wAtk":18,"fightReward":0}$json$::jsonb),
('dark-moon', 1, 5, 4, $json${"week":5,"day":4,"title":"The dead streets","heading":"The dead streets","question":"who else is in this city?","steps":[{"t":"say","text":"Your footsteps are the loudest thing in Highwall. Doors stand open on bare rooms. Wells are dry. The streets inside the wall are whole, and empty, and they climb.\n\nThen, at a crossroads, you come round a corner into a street full of soldiers.\n\nThey stand where they are, mid-stride, in armour so old that it has gone green and black. A dozen of them, strung out up the street, as if a company had been marching to his hall on the night he fell, and simply stopped.\n\nTheir faces are hidden behind their helms. None of them moves."},{"t":"notice","lines":{"Might":{"first":"That armour should have fallen in on itself long ago.","second":"Something inside it is still holding it up."},"Agility":{"first":"There is room to pass between them.","second":"Just. With your arms in."},"Intellect":{"first":"A dozen, strung out, with gaps.","second":"This is the tail of a column. The rest got further up the hill."},"Charm":{"first":"Not one of them has a face you can see.","second":"It is easier that way. It should not be."},"Craft":{"first":"Every plate still hangs true on its buckles.","second":"Whoever fastened them expected to undo them again by nightfall."},"Aim":{"first":"Every one of them is looking the same way.","second":"Up the hill, at the hall."}}},{"t":"challenge","title":"THE STREET OF SOLDIERS","desc":"It is the short way. It is between them.","options":[{"attr":"Agility","verb":"slip through without touching one"},{"attr":"Intellect","verb":"work out what you are looking at, and where it is safe to tread"}],"reward":"+500g","fail":"you lose your nerve, or your footing, and go the long way round"},{"t":"say","text":"You walk the whole street between them, close enough to smell the old iron. Nothing happens.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"A pack scrapes a breastplate. For one terrible moment every one of you waits.\n\nNothing happens. You back out the way you came, and take three streets to go round.","cond":{"on":"challenge","pass":false}},{"t":"press","title":"STOP BESIDE ONE","detail":"and look at how it stands","harder":4,"reward":"+200g, and one more detail"},{"t":"say","text":"Its left foot is forward, the heel just lifted.\n\nSo is the next one's. So is every one's. They all stopped on the same step.","cond":{"on":"press"}},{"t":"say","text":"Garrick walks last, between you and them, and does not look back once."},{"t":"say","text":"You do. From the end of the street, you look back.\n\nThe nearest one's helm is turned a little further toward you than it was."},{"t":"say","text":"Set into the wall of a house at the end of that street is a housing, its carving as crisp as the day it was cut."},{"t":"act","label":"FIND THE PATTERN"},{"t":"say","text":"The stone turns on a hidden pin.\n\n**A locked Seeker Fragment has been added to your Chest.**","fragment":true},{"t":"say","text":"That night you bar the door of an empty house two streets away, and light no fire.\n\nGarrick finds cups on a shelf, wipes the dust out of them with his sleeve, and pours: one more than there are of you, as on every night of the road. He sets the last one at the empty place by the shuttered window, the one that faces up the hill."},{"t":"say","text":"You have first watch. He sits up with you."},{"t":"choice","id":0,"labels":["WHAT ARE THEY?","WHO IS THE CUP FOR?","SAY NOTHING"],"mode":"pick","branches":[{"options":[0],"text":"*\"The page under the Kiln told you. They stood his watch.\"*"},{"options":[1],"text":"*\"Family habit. We always pour one for whoever can't be with us.\"*"},{"options":[2],"text":"Neither does he."}]},{"t":"say","text":"For a long time he is quiet. Then, looking at the cup:\n\n*\"My family's waited a long time for something. I'd like to live to see it.\"*"},{"t":"say","text":"**Was that helm turned before? Nobody is sure. And the smoke is higher up the hill. The square below the hall.**","pull":true},{"t":"summary","lines":["**THE DEAD STREETS** · Day 4","You earned: `[gold]` · Agility or Intellect `[growth]`","You learned: **a company of the king's soldiers is still standing** in the street where it stopped, on the night he fell. And one helm may have turned.","Fragments: 4 found","Tomorrow: **the square below the hall**"]}]}$json$::jsonb, $json${"dc":9,"wDef":25,"wAtk":18,"fightReward":0}$json$::jsonb),
('dark-moon', 1, 5, 5, $json${"week":5,"day":5,"title":"Below the hall","heading":"Below the hall","question":"who keeps a fire below the hall?","steps":[{"t":"say","text":"The last terrace ends in a square, and the hall fills the sky above it: a great pale building on the city's highest ground, its doors taller than houses, and shut. The heartbeat comes from behind them.\n\nAnd in the shell of a house across the square, a fire is burning."},{"t":"challenge","title":"THE FIRE IN THE SQUARE","desc":"Somebody is sitting round it.","options":[{"attr":"Agility","verb":"get close enough to hear them"},{"attr":"Aim","verb":"stay where you are, and read the whole camp from here"}],"reward":"+500g","fail":"you see the fire and little else, and a lantern swings your way"},{"t":"say","text":"You see everything, and they see nothing.\n\nNear dusk the watch changes. In the dead silence of the city, every word carries. A watchman walks out to the one at the wall, and touches his shoulder.\n\n*\"Keep the dark.\"*\n\nAnd the other answers, *\"It keeps us,\"* and goes in to the fire.\n\nOn the board propped by the wall there are nine strokes not yet crossed.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"A stone skitters under your boot. A lantern swings your way, and for one long moment a watchman stares straight at the rubble you are lying behind.\n\nThen he lowers the lantern, and goes back to the fire without a word.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"Hooded figures: four, five, more. The Order. They have made their camp facing the doors, as if they had been here all their lives.\n\nSome of them have."},{"t":"notice","lines":{"Might":{"first":"There is a woodpile against that house, stacked to the eaves.","second":"In a city where nothing grows. They carry it in."},"Agility":{"first":"The watchman at the wall has not shifted his feet once.","second":"He has done this every night since he could stand."},"Intellect":{"first":"They are camped at the doors, and have not touched them.","second":"They are not trying to get in."},"Charm":{"first":"Nobody at that fire is talking.","second":"It is the quiet of people who have said everything, long ago."},"Craft":{"first":"The hearth is built of dressed stone, blackened right through.","second":"That fire is older than anyone sitting at it."},"Aim":{"first":"A board is propped beside the wall, covered in chalk.","second":"Rows of strokes, and most of them crossed."}}},{"t":"say","text":"As the light goes, one of them rises, faces the hall, and draws the chalk through one more stroke."},{"t":"say","text":"They are not laying siege to him. They are keeping count."},{"t":"say","text":"In the broken fountain at the edge of the square, facing the hall, a housing sits low in the dry basin."},{"t":"act","label":"REACH DOWN TO IT"},{"t":"say","text":"It opens like a hand.\n\n**A locked Seeker Fragment has been added to your Chest.**\n\nPart of it can be read as it is: *…where we could watch it, and watch him.*","fragment":true},{"t":"say","text":"Somewhere close, then. Somewhere with a view of those doors."},{"t":"say","text":"**Counting down to what? You hold five pieces, and the trail began on the wall. The wall again.**","pull":true},{"t":"summary","lines":["**BELOW THE HALL** · Day 5","You earned: `[gold]` · Agility or Aim `[growth]`","You learned: **the Order is here**, camped facing his sealed doors, and has been for generations. It is not trying to get in. Each dusk it crosses out one stroke. **It is counting down.** `[On a pass: eight strokes are left. Their greeting is \"Keep the dark\" and the answer is \"It keeps us\".]`","*On a failure:* You missed something in the square. Someone at the fire may have seen it.","Fragments: 5 found","Tomorrow: **the wall again**"]}]}$json$::jsonb, $json${"dc":9,"wDef":25,"wAtk":18,"fightReward":0}$json$::jsonb),
('dark-moon', 1, 5, 6, $json${"week":5,"day":6,"title":"The wall again","heading":"The wall again","question":"where is the fifth?","steps":[{"t":"say","text":"The long way back round the street of soldiers takes all morning. Nobody looks at them twice. Nobody wants to know how many helms have turned."},{"t":"say","text":"The herald's gate. The broken stair. Above it, the wall-walk, bare to the sky, and in plain sight of the square for forty paces.\n\nYou have been heard once this season. Not again."},{"t":"choice","id":0,"labels":["POST {F1}","POST {F2}","POST {F3}"],"mode":"flavor","branches":[]},{"t":"say","text":"{F1} goes to the corner of the gate-tower, where {F1} can see the square and you can see {F1}'s hand."},{"t":"notice","lines":{"Might":{"first":"The parapet on the city side is waist-high and a yard thick.","second":"The wall under you is thicker than any wall needs to be."},"Agility":{"first":"Forty paces of open stone.","second":"Fewer, if you go when their heads are turned."},"Intellect":{"first":"They change the watch at dusk. For a moment both men are looking at each other.","second":"That is the moment."},"Charm":{"first":"From the square, a figure on the wall at dusk is only a shape.","second":"Shapes that walk like watchmen are not looked at twice."},"Craft":{"first":"One stone in the walkway has a crack along it that runs too straight.","second":"It was cut, not broken."},"Aim":{"first":"Below the walk, on the city side, there is a slit in the wall's face no wider than a hand.","second":"It looks straight at the hall."}}},{"t":"say","text":"Up the hill a lantern crosses the square, and two voices carry down through the still air.\n\n*\"Keep the dark.\"*\n\n*\"It keeps us.\"*\n\nThe watch is changing. Now."},{"t":"challenge","title":"THE OPEN WALK","desc":"Forty paces, while the watch changes above you in the square.","options":[{"attr":"Agility","verb":"low and fast, when the hand drops"},{"attr":"Charm","verb":"upright, at a watchman's pace, like someone who belongs on a wall"}],"reward":"+500g","fail":"a lantern lifts, and you finish the crossing on your belly"},{"t":"say","text":"Her hand drops. You cross. Nothing in the square so much as turns.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"Halfway, a lantern lifts in the square. You lie flat on cold stone until it goes down again, and cross the rest on your belly, a hand's width at a time.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"In the straight crack in the walkway, just where somebody keeping watch would stand, colder than the stone it lies in:"},{"t":"act","label":"TAKE IT"},{"t":"say","text":"**A locked Seeker Fragment has been added to your Chest.**\n\nThat is six.","fragment":true},{"t":"act","label":"LAY THEM OUT"},{"t":"say","text":"They settle, as they have four times before. A map, old and exact.\n\nNobody reads it out."},{"t":"act","label":"PASS IT ON"},{"t":"say","text":"It goes from hand to hand along the parapet. Each of you looks, and nods, and gives it to the next."},{"t":"say","text":"It does not point into the city at all.\n\nIt points into the wall. A room hidden in its thickness, a stone's throw from where you are crouching, with one slit of a window facing up the hill.\n\nThey kept the fifth inside their own wall, and watched him from it for as long as they lived."},{"t":"say","text":"It has been under your feet since the day you climbed up here.\n\nAnd the Order, camped in this city for longer than anyone can remember, has never known it was there."},{"t":"say","text":"As the light goes, the heartbeat comes, louder than it has ever been. Overhead, in the grey, the moon is already up: fatter than it was a week ago, nearly half.\n\nUp the hill the new watchman has taken his post. Nothing else moves. Nobody heard."},{"t":"say","text":"**The watch has changed. It is dark enough. Into the wall, tonight.**","pull":true},{"t":"summary","lines":["**THE WALL AGAIN** · Day 6","You earned: `[gold]` · Agility or Charm `[growth]`","You learned: the fifth is **in the wall itself**: a hidden room a stone's throw from the herald's gate, with one slit window on the hall. The Seekers watched him from it all their lives. **The Order has never found it. And tonight, nobody heard you.**","You hold: the map","Fragments: 6 of 6 · the map is whole","Tomorrow: **THE GATHERING** · into the wall, to the room they never found"]}]}$json$::jsonb, $json${"dc":9,"wDef":25,"wAtk":18,"fightReward":0}$json$::jsonb)
